#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "resident/domains/tasks/task_dynamic_projection.hpp"
#include "state_need.hpp"
#include "resident/domains/tasks/task_dynamic_codec.hpp"
namespace hanmo::resident {
namespace {
using namespace dynamic_codec;
template<class A>Status source(A& a,SourceRef& r){a.field("domain",r.domain);a.field("kind",r.kind);return a.field("id",r.id);}
template<class A>Status need_ref(A& a,StateNeedRef& r){a.field("need_id",r.need_id);return a.field("episode",r.episode);}
template<class A>Status goal(A& a,StateGoalRef& v){Integer tag=v.index();a.field("tag",tag);if(tag<0||tag>1)return a.reject("UnknownStateGoalKind");if(a.reading()){if(tag==0)v=CareCoverageGoal{};else v=MedicalResolutionGoal{};}if(tag==0){auto& g=std::get<CareCoverageGoal>(v);a.field("care_requirement_id",g.care_requirement_id);return a.field("subject_actor_id",g.subject_actor_id);}auto& g=std::get<MedicalResolutionGoal>(v);a.field("medical_need_id",g.medical_need_id);return a.field("patient_actor_id",g.patient_actor_id);}
template<class A>Status need(A& a,StateNeed& n){a.field("need_id",n.need_id);a.field("affair_id",n.affair_id);a.object("goal_ref",[&](auto& x){return goal(x,n.goal_ref);});a.field("episode",n.episode);a.field("source_episode",n.source_episode);a.field("source_revision",n.source_revision);a.field("opened_tick",n.opened_tick);a.optional("deadline",n.deadline,[](auto& x,auto& d){x.field("tick",d.tick);return x.field("inclusive",d.inclusive);});enumeration(a,"phase",n.phase,5);a.optional("active_claim_id",n.active_claim_id,[](auto& x,auto& v){return x.field("value",v);});a.optional("closing_source_ref",n.closing_source_ref,[](auto& x,auto& v){return source(x,v);});a.object("last_reconcile_source_ref",[&](auto& x){return source(x,n.last_reconcile_source_ref);});a.optional("previous_episode_ref",n.previous_episode_ref,[](auto& x,auto& v){return need_ref(x,v);});return a.status();}
template<class A>Status claim(A& a,StateNeedClaim& c){a.field("claim_id",c.claim_id);a.object("need_ref",[&](auto& x){return need_ref(x,c.need_ref);});a.object("assignee",[&](auto& x){return subject(x,c.assignee);});a.field("executor_actor_id",c.executor_actor_id);a.field("task_contract_id",c.task_contract_id);a.field("accepted_source_revision",c.accepted_source_revision);a.field("accepted_tick",c.accepted_tick);a.field("claim_until_tick",c.claim_until_tick);enumeration(a,"phase",c.phase,3);a.optional("release_reason",c.release_reason,[](auto& x,auto& v){return x.field("value",v);});a.object("acceptance_ref",[&](auto& x){return source(x,c.acceptance_ref);});return a.status();}
template<class A>Status catalog(A&a,CatalogIdentity&v){a.field("content_id",v.content_id);a.field("content_version",v.content_version);a.field("content_digest",v.content_digest);a.field("ruleset_id",v.ruleset_id);a.field("schema_sha256",v.schema_sha256);a.optional("pack_set_digest",v.pack_set_digest,[](auto&c,auto&x){return c.field("value",x);});a.sequence("module_versions",v.module_versions,[](auto&c,auto&x){c.field("module",x.first);return c.field("version",x.second);});return a.field("artifact_sha256",v.artifact_sha256);}
template<class A>Status rule(A&a,FixedLockedRuleInput&v){a.object("catalog_identity",[&](auto&x){return catalog(x,v.catalog_identity);});return a.field("rule_ref",v.rule_ref);}
template<class A>Status gate(A&a,StateDeadlineGateRef&v){Integer kind=v.index();a.field("kind",kind);if(kind<0||kind>1)return a.reject("UnknownStateDeadlineGate");if(a.reading()){if(kind==0)v=StateNeedDeadlineGateRef{};else v=StateClaimDeadlineGateRef{};}if(kind==0)return a.object("need_ref",[&](auto&x){return need_ref(x,std::get<StateNeedDeadlineGateRef>(v).need_ref);});return a.field("claim_id",std::get<StateClaimDeadlineGateRef>(v).claim_id);}
template<class A>Status opening_need(A&a,StateNeedDeadlineOpening&v){a.object("need_ref",[&](auto&x){return need_ref(x,v.need_ref);});a.optional("claim",v.claim,[](auto&x,auto&c){x.field("claim_id",c.claim_id);x.field("task_contract_id",c.task_contract_id);return x.object("acceptance_ref",[&](auto&y){return source(y,c.acceptance_ref);});});return a.object("rule_ref",[&](auto&x){return rule(x,v.rule_ref);});}
template<class A>Status state(A&a,StateNeedState&s,Integer version){
 if(version!=1&&version!=2)return a.reject("UnsupportedStateNeedPhysicalVersion");if(a.reading())s.exact_period_openings=version==2;else if(s.exact_period_openings!=(version==2)||(!s.exact_period_openings&&!s.period_openings.empty()))return a.reject("StateNeedPhysicalVersionMismatch");
 table(a,"needs",s.needs,[](auto&x,auto&v){return need(x,v);});table(a,"claims",s.claims,[](auto&x,auto&v){return claim(x,v);});
 table(a,"deadline_closures",s.deadline_closures,[](auto&x,auto&v){x.field("need_id",v.need_id);x.field("episode",v.episode);x.optional("claim_id",v.claim_id,[](auto&c,auto&id){return c.field("value",id);});x.object("deadline_gate_ref",[&](auto&c){return gate(c,v.deadline_gate_ref);});x.field("deadline_closed_at_tick",v.deadline_closed_at_tick);x.object("closing_source_ref",[&](auto&c){return source(c,v.closing_source_ref);});return x.object("rule_ref",[&](auto&c){return rule(c,v.rule_ref);});});
 if(version==2)table(a,"period_openings",s.period_openings,[](auto&x,auto&v){x.field("period_id",v.period_id);x.object("opened_at",[&](auto&c){return exact_moment(c,v.opened_at);});x.field("through_tick",v.through_tick);return x.sequence("opening_needs",v.opening_needs,[](auto&c,auto&n){return opening_need(c,n);});});
 auto result=a.status();if(result.ok&&a.reading())return rebuild_state_need_indexes(s);return result;
}
}
Outcome<StateNeedState> decode_state_needs(const BoundaryValue& value,Integer version){StateNeedState s;dynamic_codec::JsonArchive a(value);auto r=state(a,s,version);if(r.ok)r=a.finish();return r.ok?Outcome<StateNeedState>{true,std::move(s),{}}:Outcome<StateNeedState>{false,{},r.error};}
Status emit_state_needs_projection(ProjectionWriter&sink,std::string_view key,const StateNeedState&value){return dynamic_projection::emit(sink,key,value,[&](auto&a,auto&v){return state(a,v,value.exact_period_openings?2:1);});}
Outcome<BoundaryValue> encode_state_needs(const StateNeedState&value){return dynamic_projection::encode(value,[&](auto&a,auto&v){return state(a,v,value.exact_period_openings?2:1);});}
Status visit_state_needs_checkpoint(CodecVisitor& a,StateNeedState& s,Integer version){return state(a,s,version);}
}
